{
  "rules": [
    "Persistent positive bias: model forecasts are systematically too high vs. realized prices (often by ~1–5 EUR, occasionally more). Apply a downward level shift to the whole path, larger when the recent trend is down.",
    "Downtrend underreaction / lag: after a clear break lower, the model decays too slowly and keeps prices elevated. Increase negative slope (steepen the decline) for the first 1–2 weeks when the last 10–20 days show sustained lower highs/lows.",
    "Overshoot on rebounds: when the market bounces after a selloff, the model projects an overly strong recovery (especially at 2–4 week horizons). Damp rebound amplitude (e.g., shrink positive deviations from the recent low).",
    "Horizon-specific error: bias grows with horizon—near-term errors are smaller; weeks 3–4 are most overestimated. Use a horizon-dependent correction (increasing downward adjustment with lead time).",
    "Mean-reversion miscalibration: the model reverts toward a too-high anchor (recent history) rather than the new regime level after a drawdown. Re-anchor mean reversion to a lower baseline when the 30d history shows a sharp step-down (recent price far below 30d average)."
  ],
  "meta": {
    "observed_pattern_summary": "Across examples, forecasts remain above outcomes during a pronounced selloff and subsequently overstate the strength of any recovery; the overestimation is more pronounced at longer horizons."
  }
}
